    var nDigits int32 = Abc_Base10Log( nVars );

    assert(nVars > 0, "nVars > 0");
    fmt.Fprintf(pFile, ".model ADD%d\n", nVars);

    fmt.Fprintf(pFile, ".inputs");
    for  i = 0; i < nVars; i++  {
